package com.example.rokidkeyboardbridge;
import org.json.*;import java.util.concurrent.atomic.AtomicLong;
/** Observation only: never changes a payload, response, retry, or tool decision. No raw content retained. */
final class ConversationTrace {
 private static final AtomicLong sequence=new AtomicLong();private static final ThreadLocal<JSONObject> active=new ThreadLocal<>();private static volatile JSONObject latest=new JSONObject();
 static long begin(String request,String reference,int contextChars){long serial=sequence.incrementAndGet();try{JSONObject trace=new JSONObject().put("serial",serial).put("request",request!=null&&request.matches("[a-f0-9]{64}")?request:"").put("at",System.currentTimeMillis()).put("reference",reference!=null&&reference.matches("auto|image|none|inbox")?reference:"unknown").put("contextChars",Math.max(0,contextChars)).put("responseObserved",false).put("searchObserved",false).put("queries",0).put("sources",0).put("phase","RUNNING");active.set(trace);publish(trace);}catch(Exception ignored){}return serial;}
 static void observe(String raw){JSONObject trace=active.get();if(trace==null||raw==null||raw.length()>2000000)return;try{JSONObject response=new JSONObject(raw);JSONArray candidates=response.optJSONArray("candidates");if(candidates==null||candidates.length()==0)return;JSONObject candidate=candidates.optJSONObject(0);if(candidate==null)return;JSONObject grounding=candidate.optJSONObject("groundingMetadata");int queries=grounding==null||grounding.optJSONArray("webSearchQueries")==null?0:grounding.getJSONArray("webSearchQueries").length(),sources=grounding==null||grounding.optJSONArray("groundingChunks")==null?0:grounding.getJSONArray("groundingChunks").length();trace.put("responseObserved",true).put("searchObserved",trace.optBoolean("searchObserved")||queries>0||sources>0).put("queries",Math.max(trace.optInt("queries"),queries)).put("sources",Math.max(trace.optInt("sources"),sources));String reason=candidate.optString("finishReason");trace.put("finishReason",reason.matches("STOP|MAX_TOKENS|SAFETY|RECITATION|OTHER|BLOCKLIST|PROHIBITED_CONTENT|SPII|MALFORMED_FUNCTION_CALL")?reason:"UNKNOWN");publish(trace);}catch(Exception ignored){}}
 private static void publish(JSONObject trace){try{if(trace.optLong("serial")==sequence.get())latest=new JSONObject(trace.toString());}catch(Exception ignored){}}
 static void end(long serial,boolean success){JSONObject trace=active.get();try{if(trace!=null&&trace.optLong("serial")==serial){trace.put("phase",success?"RETURNED":"FAILED").put("endedAt",System.currentTimeMillis());publish(trace);}}catch(Exception ignored){}finally{active.remove();}}
 static JSONObject snapshot(){try{return new JSONObject(latest.toString());}catch(Exception ignored){return new JSONObject();}}
 private ConversationTrace(){}
}
